"""Exception hierarchy for minilang."""


class MiniLangError(Exception):
    """Base class for all minilang errors.

    ``position`` is the 0-based offset into the source of the offending
    character or token, or None when not applicable (e.g. EvalError).
    """

    def __init__(self, message, position=None):
        super().__init__(message)
        self.message = message
        self.position = position

    def __str__(self):
        # Plain message only: no position prefix (rule 29).
        return self.message


class LexError(MiniLangError):
    """Raised while tokenizing."""


class ParseError(MiniLangError):
    """Raised while parsing."""


class EvalError(MiniLangError):
    """Raised while evaluating."""

"""Recursive-descent parser for minilang.

Grammar (loosest to tightest binding):

    expr          := or_expr
    or_expr       := and_expr ( "or" and_expr )*
    and_expr      := not_expr ( "and" not_expr )*
    not_expr      := "not" not_expr | comparison
    comparison    := additive ( ( "==" | "!=" | "<" | "<=" | ">" | ">=" ) additive )?
    additive      := multiplicative ( ( "+" | "-" ) multiplicative )*
    multiplicative:= unary ( ( "*" | "/" | "%" ) unary )*
    unary         := "-" unary | power
    power         := primary ( "^" unary )?
    primary       := NUMBER | STRING | "true" | "false"
                   | IDENT | IDENT "(" [ expr ( "," expr )* ] ")"
                   | "(" expr ")"
"""

from .errors import ParseError
from .lexer import tokenize

_COMPARISON_OPS = frozenset({"==", "!=", "<", "<=", ">", ">="})


class _Node:
    __slots__ = ()


class Num(_Node):
    __slots__ = ("value",)

    def __init__(self, value):
        self.value = value


class Str(_Node):
    __slots__ = ("value",)

    def __init__(self, value):
        self.value = value


class Bool(_Node):
    __slots__ = ("value",)

    def __init__(self, value):
        self.value = value


class Var(_Node):
    __slots__ = ("name",)

    def __init__(self, name):
        self.name = name


class Call(_Node):
    __slots__ = ("name", "args")

    def __init__(self, name, args):
        self.name = name
        self.args = args


class Unary(_Node):
    __slots__ = ("op", "operand")

    def __init__(self, op, operand):
        self.op = op
        self.operand = operand


class Binary(_Node):
    __slots__ = ("op", "left", "right")

    def __init__(self, op, left, right):
        self.op = op
        self.left = left
        self.right = right


class _Parser:
    def __init__(self, tokens, source):
        self.tokens = tokens
        self.pos = 0
        self.source = source

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def advance(self):
        token = self.tokens[self.pos]
        self.pos += 1
        return token

    def error(self, message, token=None):
        # At end of input, report the position just past the last character.
        position = token.position if token is not None else len(self.source)
        raise ParseError(message, position)

    def is_op(self, token, *ops):
        return token is not None and token.kind == "OP" and token.value in ops

    def is_keyword(self, token, *words):
        return token is not None and token.kind == "KEYWORD" and token.value in words

    # expr := or_expr
    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        left = self.parse_and()
        while self.is_keyword(self.peek(), "or"):
            self.advance()
            left = Binary("or", left, self.parse_and())
        return left

    def parse_and(self):
        left = self.parse_not()
        while self.is_keyword(self.peek(), "and"):
            self.advance()
            left = Binary("and", left, self.parse_not())
        return left

    def parse_not(self):
        token = self.peek()
        if self.is_keyword(token, "not"):
            self.advance()
            return Unary("not", self.parse_not())
        return self.parse_comparison()

    def parse_comparison(self):
        left = self.parse_additive()
        token = self.peek()
        if self.is_op(token, *_COMPARISON_OPS):
            op = self.advance().value
            right = self.parse_additive()
            nxt = self.peek()
            if self.is_op(nxt, *_COMPARISON_OPS):
                # Comparison is non-associative: "1 < 2 < 3" is a ParseError.
                raise ParseError("comparison operators are non-associative", nxt.position)
            return Binary(op, left, right)
        return left

    def parse_additive(self):
        left = self.parse_multiplicative()
        while self.is_op(self.peek(), "+", "-"):
            op = self.advance().value
            left = Binary(op, left, self.parse_multiplicative())
        return left

    def parse_multiplicative(self):
        left = self.parse_unary()
        while self.is_op(self.peek(), "*", "/", "%"):
            op = self.advance().value
            left = Binary(op, left, self.parse_unary())
        return left

    def parse_unary(self):
        if self.is_op(self.peek(), "-"):
            self.advance()
            return Unary("-", self.parse_unary())
        return self.parse_power()

    def parse_power(self):
        # "^" is right-associative and its right operand is a unary, so
        # 2 ^ 3 ^ 2 == 2 ^ (3 ^ 2) and 2 ^ -1 is valid.
        base = self.parse_primary()
        if self.is_op(self.peek(), "^"):
            self.advance()
            return Binary("^", base, self.parse_unary())
        return base

    def parse_primary(self):
        token = self.peek()
        if token is None:
            self.error("unexpected end of input")
        if token.kind == "NUMBER":
            self.advance()
            return Num(token.value)
        if token.kind == "STRING":
            self.advance()
            return Str(token.value)
        if token.kind == "KEYWORD" and token.value in ("true", "false"):
            self.advance()
            return Bool(token.value == "true")
        if token.kind == "IDENT":
            self.advance()
            if self.is_op(self.peek(), "("):
                self.advance()
                args = []
                if not self.is_op(self.peek(), ")"):
                    args.append(self.parse_expr())
                    while self.is_op(self.peek(), ","):
                        self.advance()
                        args.append(self.parse_expr())
                closing = self.peek()
                if not self.is_op(closing, ")"):
                    self.error("expected ')'", closing)
                self.advance()
                return Call(token.value, args)
            return Var(token.value)
        if self.is_op(token, "("):
            self.advance()
            node = self.parse_expr()
            closing = self.peek()
            if not self.is_op(closing, ")"):
                self.error("expected ')'", closing)
            self.advance()
            return node
        self.error(f"unexpected token: {token.value!r}", token)


def parse(source):
    """Parse source into an AST. Never evaluates anything."""
    tokens = tokenize(source)
    parser = _Parser(tokens, source)
    node = parser.parse_expr()
    leftover = parser.peek()
    if leftover is not None:
        raise ParseError(f"unexpected trailing input: {leftover.value!r}", leftover.position)
    return node

"""Built-in functions for minilang.

Each built-in takes a list of already-evaluated arguments and raises
EvalError on arity or type violations. ``if`` is intentionally absent:
it is lazy and therefore handled directly by the evaluator.
"""

from .errors import EvalError


def format_number(value):
    """REPL/rule-33 number formatting: integral floats print with no
    decimal part, everything else uses repr's shortest form."""
    if value.is_integer():
        return str(int(value))
    return repr(value)


def typename(value):
    if type(value) is bool:
        return "boolean"
    if type(value) is float:
        return "number"
    return "string"


def _arity(name, args, expected):
    if len(args) != expected:
        raise EvalError(f"{name}() takes {expected} argument(s), got {len(args)}")


def _number(name, value):
    if type(value) is not float:
        raise EvalError(f"{name}() expects a number, got {typename(value)}")
    return value


def _string(name, value):
    if type(value) is not str:
        raise EvalError(f"{name}() expects a string, got {typename(value)}")
    return value


def _builtin_abs(args):
    _arity("abs", args, 1)
    return abs(_number("abs", args[0]))


def _minmax(name, args, op):
    # Interpretation choice: variadic built-ins report "at least 1".
    if len(args) < 1:
        raise EvalError(f"{name}() takes at least 1 argument(s), got {len(args)}")
    for value in args:
        _number(name, value)
    return float(op(args))


def _builtin_min(args):
    return _minmax("min", args, min)


def _builtin_max(args):
    return _minmax("max", args, max)


def _builtin_round(args):
    # Interpretation choice: round accepts 1 or 2 arguments.
    if len(args) not in (1, 2):
        raise EvalError(f"round() takes 1 or 2 argument(s), got {len(args)}")
    x = _number("round", args[0])
    if len(args) == 1:
        return float(round(x))
    n = _number("round", args[1])
    if not n.is_integer():
        raise EvalError("round() argument 2 must be a whole number")
    return float(round(x, int(n)))


def _builtin_len(args):
    _arity("len", args, 1)
    return float(len(_string("len", args[0])))


def _builtin_upper(args):
    _arity("upper", args, 1)
    return _string("upper", args[0]).upper()


def _builtin_lower(args):
    _arity("lower", args, 1)
    return _string("lower", args[0]).lower()


def _builtin_str(args):
    _arity("str", args, 1)
    value = args[0]
    if type(value) is bool:
        return "true" if value else "false"
    if type(value) is float:
        return format_number(value)
    return value


def _builtin_num(args):
    _arity("num", args, 1)
    text = _string("num", args[0])
    try:
        return float(text)
    except ValueError:
        raise EvalError(f"num() cannot parse {text!r} as a number") from None


BUILTINS = {
    "abs": _builtin_abs,
    "min": _builtin_min,
    "max": _builtin_max,
    "round": _builtin_round,
    "len": _builtin_len,
    "upper": _builtin_upper,
    "lower": _builtin_lower,
    "str": _builtin_str,
    "num": _builtin_num,
}

"""Evaluator for minilang ASTs."""

from .builtins import BUILTINS, typename
from .errors import EvalError
from .parser import Binary, Bool, Call, Num, Str, Unary, Var, parse


def evaluate(source, env=None):
    """Parse and evaluate source, returning a float, str or bool.

    The given env mapping is only read, never mutated.
    """
    node = parse(source)
    return _eval(node, env if env is not None else {})


def _require_bool(value, context):
    if type(value) is not bool:
        raise EvalError(f"{context} requires a boolean, got {typename(value)}")
    return value


def _require_number(value, context):
    if type(value) is not float:
        raise EvalError(f"{context} requires a number, got {typename(value)}")
    return value


def _eval(node, env):
    if isinstance(node, (Num, Str, Bool)):
        return node.value

    if isinstance(node, Var):
        if node.name not in env:
            raise EvalError(f"undefined variable: {node.name}")
        value = env[node.name]
        if type(value) not in (float, str, bool):
            raise EvalError(f"unsupported value for {node.name}: {value!r}")
        return value

    if isinstance(node, Unary):
        if node.op == "not":
            return not _require_bool(_eval(node.operand, env), "not")
        return -_require_number(_eval(node.operand, env), "unary '-'")

    if isinstance(node, Binary):
        return _eval_binary(node, env)

    # Call
    if node.name == "if":
        # Lazy conditional: only the taken branch is evaluated.
        if len(node.args) != 3:
            raise EvalError(f"if() takes 3 argument(s), got {len(node.args)}")
        cond = _require_bool(_eval(node.args[0], env), "if() condition")
        return _eval(node.args[1] if cond else node.args[2], env)

    fn = BUILTINS.get(node.name)
    if fn is None:
        # No fall-back to variables: a call target must be a built-in.
        raise EvalError(f"undefined function: {node.name}")
    return fn([_eval(arg, env) for arg in node.args])


def _eval_binary(node, env):
    op = node.op

    if op == "and":
        left = _require_bool(_eval(node.left, env), "and")
        if not left:
            return False
        return _require_bool(_eval(node.right, env), "and")

    if op == "or":
        left = _require_bool(_eval(node.left, env), "or")
        if left:
            return True
        return _require_bool(_eval(node.right, env), "or")

    left = _eval(node.left, env)
    right = _eval(node.right, env)

    if op == "+":
        if type(left) is float and type(right) is float:
            return left + right
        if type(left) is str and type(right) is str:
            return left + right
        raise EvalError(f"cannot add {typename(left)} and {typename(right)}")

    if op in ("-", "*", "/", "%"):
        _require_number(left, f"'{op}'")
        _require_number(right, f"'{op}'")
        if op == "-":
            return left - right
        if op == "*":
            return left * right
        if op == "/":
            if right == 0.0:
                raise EvalError("division by zero")
            return left / right
        if right == 0.0:
            raise EvalError("modulo by zero")
        return left % right  # Python semantics: result takes divisor's sign

    if op == "^":
        _require_number(left, "'^'")
        _require_number(right, "'^'")
        try:
            result = left ** right
        except (OverflowError, ZeroDivisionError) as exc:
            raise EvalError(f"invalid power operation: {exc}") from None
        if isinstance(result, complex):
            raise EvalError("power result is not a real number")
        return result

    if op == "==":
        # Different types are never equal (True == 1.0 must be False).
        return type(left) is type(right) and left == right

    if op == "!=":
        return not (type(left) is type(right) and left == right)

    # Ordering comparisons: numbers with numbers, strings with strings.
    same_orderable = (type(left) is float and type(right) is float) or (
        type(left) is str and type(right) is str
    )
    if not same_orderable:
        raise EvalError(f"cannot compare {typename(left)} with {typename(right)}")
    if op == "<":
        return left < right
    if op == "<=":
        return left <= right
    if op == ">":
        return left > right
    return left >= right

"""REPL for minilang, runnable as ``python -m minilang``.

Reads one line at a time from stdin. No prompt, no banner, no summary.
"""

import re
import sys

from . import evaluate
from .builtins import format_number
from .errors import MiniLangError

# "<ident> = <expr>" where the '=' is a single one, not part of '=='.
_ASSIGN_RE = re.compile(r"^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=(?!=)")


def _escape_string(value):
    return (
        value.replace("\\", "\\\\")
        .replace('"', '\\"')
        .replace("\n", "\\n")
        .replace("\t", "\\t")
        .replace("\r", "\\r")
    )


def format_value(value):
    if type(value) is bool:
        return "true" if value else "false"
    if type(value) is float:
        return format_number(value)
    return '"' + _escape_string(value) + '"'


def main():
    env = {}
    for raw_line in sys.stdin:
        line = raw_line.strip()
        if not line:
            continue
        if line == ":quit":
            return 0
        if line == ":vars":
            for name in sorted(env):
                print(f"{name} = {format_value(env[name])}")
            continue
        match = _ASSIGN_RE.match(raw_line)
        if match:
            name = match.group(1)
            expr = raw_line[match.end() :]
            try:
                value = evaluate(expr, env)
            except MiniLangError as exc:
                print(f"error: {exc}")
                continue
            # Store only on success, so failures leave env unchanged.
            env[name] = value
            continue
        try:
            print(format_value(evaluate(raw_line, env)))
        except MiniLangError as exc:
            print(f"error: {exc}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""Test suite for minilang."""

import subprocess
import sys
from pathlib import Path

import pytest

from minilang import (
    EvalError,
    LexError,
    MiniLangError,
    ParseError,
    evaluate,
    parse,
    tokenize,
)

ROOT = Path(__file__).resolve().parent.parent


def run_repl(input_text):
    return subprocess.run(
        [sys.executable, "-m", "minilang"],
        input=input_text,
        capture_output=True,
        text=True,
        cwd=ROOT,
    )


# ---------------------------------------------------------------- lexer


def test_lex_numbers():
    tokens = tokenize("123 1.5 .5 1e3 1.2e-4 2E+8")
    assert [t.kind for t in tokens] == ["NUMBER"] * 6
    assert [t.value for t in tokens] == [123.0, 1.5, 0.5, 1000.0, 1.2e-4, 2e8]
    assert all(type(t.value) is float for t in tokens)


def test_lex_number_trailing_dot_is_error():
    with pytest.raises(LexError):
        tokenize("1.")


def test_lex_strings_and_escapes():
    tokens = tokenize(r'"a\nb\t\"q\\"')
    assert tokens[0].kind == "STRING"
    assert tokens[0].value == 'a\nb\t"q\\'


def test_lex_bad_escape():
    with pytest.raises(LexError):
        tokenize('"bad \\q escape"')


def test_lex_unterminated_string():
    with pytest.raises(LexError):
        tokenize('"unterminated')


def test_lex_newline_inside_string():
    with pytest.raises(LexError):
        tokenize('"a\nb"')


def test_lex_comments_are_ignored():
    tokens = tokenize("1 + 1 # a comment\n# whole line\n2")
    assert [t.value for t in tokens] == [1.0, "+", 1.0, 2.0]


def test_lex_single_equals_is_error():
    with pytest.raises(LexError):
        tokenize("1 = 2")


def test_lex_unexpected_character():
    with pytest.raises(LexError):
        tokenize("a @ b")


def test_lex_keywords_and_idents():
    tokens = tokenize("true false and or not foo _bar9")
    assert [t.kind for t in tokens] == ["KEYWORD"] * 5 + ["IDENT"] * 2
    assert tokens[5].value == "foo"


def test_lex_token_positions():
    tokens = tokenize("12 +  \"ab\"")
    assert [(t.kind, t.position) for t in tokens] == [
        ("NUMBER", 0),
        ("OP", 3),
        ("STRING", 6),
    ]
    # No EOF token is produced.
    assert all(t.kind != "EOF" for t in tokens)


def test_lex_error_position():
    try:
        tokenize("1 + @")
    except LexError as exc:
        assert exc.position == 4
    else:
        raise AssertionError("expected LexError")


# ---------------------------------------------------------------- parser


def test_parse_does_not_evaluate():
    parse("1 / 0")


def test_parse_trailing_input_is_error():
    with pytest.raises(ParseError):
        parse("1 2")


def test_parse_unclosed_paren_is_error():
    with pytest.raises(ParseError):
        parse("(1")


def test_parse_empty_source_is_error():
    with pytest.raises(ParseError):
        parse("")


def test_parse_comment_only_source_is_error():
    with pytest.raises(ParseError):
        parse("# only a comment")


def test_parse_comparison_is_non_associative():
    with pytest.raises(ParseError):
        parse("1 < 2 < 3")


def test_parse_error_position():
    try:
        parse("1 + )")
    except ParseError as exc:
        assert exc.position == 4
    else:
        raise AssertionError("expected ParseError")


# ---------------------------------------------------------------- evaluation: precedence


def test_additive_and_multiplicative_precedence():
    assert evaluate("1 + 2 * 3") == 7.0
    assert evaluate("(1 + 2) * 3") == 9.0


def test_left_associativity():
    assert evaluate("10 - 4 - 3") == 3.0
    assert evaluate("16 / 4 / 2") == 2.0


def test_power_is_right_associative():
    assert evaluate("2 ^ 3 ^ 2") == 512.0


def test_unary_minus_binds_looser_than_power():
    assert evaluate("-2 ^ 2") == -4.0


def test_power_negative_exponent():
    assert evaluate("2 ^ -1") == 0.5


def test_not_binds_looser_than_comparison():
    assert evaluate("not 1 == 2") is True


def test_and_binds_tighter_than_or():
    assert evaluate("true or false and false") is True
    assert evaluate("false and true or true") is True


def test_modulo_follows_python_sign_rules():
    assert evaluate("7 % 3") == 1.0
    assert evaluate("-7 % 3") == 2.0


# ---------------------------------------------------------------- evaluation: semantics


def test_string_concatenation():
    assert evaluate('"a" + "b"') == "ab"


def test_mixed_addition_is_error():
    with pytest.raises(EvalError):
        evaluate('"a" + 1')


def test_division_by_zero():
    with pytest.raises(EvalError, match="division by zero"):
        evaluate("1 / 0")


def test_modulo_by_zero():
    with pytest.raises(EvalError, match="modulo by zero"):
        evaluate("1 % 0")


def test_power_non_real_result():
    with pytest.raises(EvalError):
        evaluate("(-8) ^ 0.5")


def test_equality_across_types():
    assert evaluate("true == 1") is False
    assert evaluate('"1" == 1') is False
    assert evaluate('1 != "a"') is True
    assert evaluate("1 == 1") is True
    assert evaluate('"a" == "a"') is True


def test_string_ordering():
    assert evaluate('"abc" < "abd"') is True
    assert evaluate('"b" >= "a"') is True


def test_ordering_type_mismatch_is_error():
    with pytest.raises(EvalError):
        evaluate("1 < 'a'".replace("'", '"'))
    with pytest.raises(EvalError):
        evaluate("true < 1")


def test_short_circuit_and():
    assert evaluate("false and 1 / 0") is False


def test_short_circuit_or():
    assert evaluate("true or 1 / 0") is True


def test_and_or_require_booleans():
    with pytest.raises(EvalError):
        evaluate("1 and true")
    with pytest.raises(EvalError):
        evaluate("true and 1")
    with pytest.raises(EvalError):
        evaluate("0 or true")


def test_not_requires_boolean():
    with pytest.raises(EvalError):
        evaluate("not 1")


def test_unary_minus_requires_number():
    with pytest.raises(EvalError):
        evaluate('-"a"')


def test_undefined_variable():
    with pytest.raises(EvalError, match="undefined variable: foo"):
        evaluate("foo + 1")


def test_undefined_function():
    with pytest.raises(EvalError, match="undefined function: foo"):
        evaluate("foo(1)")


def test_call_does_not_fall_back_to_variable():
    with pytest.raises(EvalError, match="undefined function"):
        evaluate("f()", {"f": 1.0})


def test_env_variable_lookup():
    assert evaluate("x * 2", {"x": 21.0}) == 42.0


def test_env_is_not_mutated():
    env = {"x": 21.0}
    evaluate("x + 1", env)
    assert env == {"x": 21.0}


def test_env_rejects_int_values():
    with pytest.raises(EvalError, match=r"unsupported value for x: 2"):
        evaluate("x", {"x": 2})


def test_env_rejects_other_types():
    with pytest.raises(EvalError, match="unsupported value for x"):
        evaluate("x", {"x": [1]})


# ---------------------------------------------------------------- built-ins


def test_builtin_abs():
    assert evaluate("abs(-3.5)") == 3.5
    assert evaluate("abs(2)") == 2.0


def test_builtin_min_max():
    assert evaluate("min(3, 1, 2)") == 1.0
    assert evaluate("max(3, 1, 2)") == 3.0
    assert evaluate("min(5)") == 5.0


def test_builtin_min_max_require_numbers():
    with pytest.raises(EvalError):
        evaluate('min(1, "a")')
    with pytest.raises(EvalError):
        evaluate("max()")


def test_builtin_round():
    assert evaluate("round(2.5)") == 2.0  # banker's rounding
    assert evaluate("round(3.5)") == 4.0
    assert evaluate("round(2.675, 2)") == 2.68
    with pytest.raises(EvalError):
        evaluate("round(1.5, 0.5)")


def test_builtin_len():
    assert evaluate('len("hello")') == 5.0
    assert type(evaluate('len("hi")')) is float


